D=Path(__file__).resolve().parent;R=D.parents[2];A=R/'art/creatures/cervarco-family-v1';G=Path('C:/Users/user/.codex/generated_images/01a17924-9eaf-7951-8ded-c6920198ad3f')
specs=[
 ('brotim','Brotim','Bebê','exec-fb7de5ed-082a-41c3-9f8f-9f44c96b4579.png','Sentir a corrente','Corpo único em semente/barquinho, duas orelhas, dois botões sem galhada ramificada, sem membros.','Orelhas estabilizam seu corpo enquanto aprende a seguir a linha.','Sem apoios para se fixar ao chão.'),
 ('galhim','Galhim','Criança','exec-8767977a-ac34-49ff-a4a3-1dac19bbd217.png','Encontrar um caminho','Quadrúpede arredondado, quatro cascos fendidos, galhadas pequenas em Y com membranas rosadas e peito de pipa.','Primeiros apoios dão coragem para explorar sem perder o grupo.','As galhadas pequenas sustentam pouca tensão.'),
 ('cervela','Cervela','Jovem','exec-896f624d-8930-42e1-a62c-788b29747e85.png','Orientar a passagem','Cervo quadrúpede esguio, quatro cascos, pescoço longo, galhadas-armação de três pontas por lado.','De seguir trilhas passa a indicar caminhos com a tensão das linhas.','A largura da armação dificulta passagens estreitas.'),
 ('cervarco','Cervarco','Adulto','exec-08672004-3f70-457e-bb41-b5448498c16d.png','Tecer uma passagem','Cervo-centauro: quatro pernas com cascos e dois braços ligados ao torso ereto, galhadas-armação e placas de proteção.','Usa mãos e galhadas para coordenar linhas e ajudar outros a atravessar.','Tecelagem exige quatro apoios e interrompe a marcha.')]
nodes=[]
for i,(id,name,age,file,action,anatomy,story,cost) in enumerate(specs):
 P=A/id/'concept-v1';P.mkdir(parents=True,exist_ok=True);shutil.copy2(G/file,P/'concept.png')
 (P/'brief.md').write_text(f'# {name} — {age}\n\n## Definido pelo autor\nCriar uma linha evolutiva de cervo no universo Soulmonsters.\n\n## Proposta\nNome {name}; maturidade {age}. {anatomy} Verbo: {action}. {story} Limitação: {cost}\n\nIdentidade: vinho, ocre, marfim, verde escuro, cobre, membranas rosadas, orelhas horizontais e cauda-leque com rabiola de folhas. Papel e armação fazem parte da anatomia; alma continua na rabiola. Galhadas de condução e papel de guia/tecelão são propostas, não cânone.\n\n## Desconhecido\nElementos, requisitos, habitat, participação na história, montaria, números e habilidades não definidos.\n',encoding='utf-8')
 review=anatomy+' Conferida continuidade do corpo, raízes de orelhas/galhadas, apoios e rabiola. '
 if id=='cervarco':review+='Seis membros presentes: quatro pernas e dois braços. Mãos ligadas a cotovelos/ombros; galhadas e mãos conduzem linhas até um losango de demonstração. O funcionamento e a amplitude exigem vistas e ações antes de rig. '
 if id=='galhim':review+='Uma pata dianteira levantada; três apoios no chão, quatro membros presentes. Quantidade de pintas e detalhes de dobras diverge do prompt; é o desenho atual a avaliar. '
 review+='Uma única imagem em três quartos não valida anatomia em todos os ângulos. Há transições suaves residuais e contorno predominantemente contínuo: concept 2D mangá, não pixel art técnico. Fundo branco opaco. Não recortado, animado ou integrado. Em avaliação.'
 (P/'revisao.md').write_text('# Conferência\n\n'+review,encoding='utf-8')
 with Image.open(P/'concept.png') as im:size=list(im.size);mode=im.mode
 (P/'manifest.json').write_text(json.dumps(dict(tool='image_gen.imagegen built-in',source=str(G/file),sha256=hashlib.sha256((P/'concept.png').read_bytes()).hexdigest(),dimensions=size,mode=mode,alpha=False,prompt='prompt.txt',reference_role='Own adolescent ancestry' if id=='cervarco' else 'Text only',external_generation_inputs=False,decision_status='proposed',production_status='concept',implementation_status='not_integrated'),ensure_ascii=False,indent=2),encoding='utf-8')
 nodes.append(dict(id=id,name=name,kind='stage',stage=i+1,maturity=age,identity=anatomy,story=story,action=action,tradeoff=cost,decision_status='proposed',production_status='concept',art=Path(os.path.relpath(P/'concept.png',D)).as_posix(),brief=Path(os.path.relpath(P/'brief.md',D)).as_posix()))
edges=[dict(**{'from':nodes[i]['id'],'to':nodes[i+1]['id']},kind='reweaving',reason=r,decision_status='proposed') for i,r in enumerate(['Corpo flutuante ganha quatro apoios para exploração.','Galhadas pequenas viram armação de condução e corpo ganha alcance.','A condução amadurece em tecelagem: braços coordenam linhas e quatro pernas ancoram o peso.'])]
(D/'chart.json').write_text(json.dumps(dict(family_id='cervarco-family-v1',scope='Quatro concepts, nomes e funções propostos; sem integração.',nodes=nodes,edges=edges),ensure_ascii=False,indent=2),encoding='utf-8')
sources=[dict(title='Reindeer (Caribou)',entity='San Diego Zoo Wildlife Alliance',url='https://animals.sandiegozoo.org/animals/reindeer-caribou',access='2026-11-04',fact='Galhadas possuem haste principal e ramificações; perfil descreve vida em grupos.',interpretation='Uma estrutura ramificada pode orientar a identidade da família sem aumentar indefinidamente o número de pontas.',proposed_use='Galhadas como armações; guia de caminhos é invenção do projeto, não comportamento biológico afirmado.'),dict(title='Why Reindeer Rule',entity='San Diego Zoo Wildlife Alliance',url='https://adminzoonooz.sandiegozoo.org/story-hub/2018/12/10/why-reindeer-rule',access='2026-11-04',fact='Descreve casco dividido em duas partes que se abrem para apoiar peso.',proposed_use='Distinguir cascos fendidos de pés equinos ou patas com dedos; não generalizar adaptação polar para todo cervo.')]
(D/'fontes.json').write_text(json.dumps(sources,ensure_ascii=False,indent=2),encoding='utf-8')
(D/'CHART.md').write_text('# Linha do cervo — proposta\n\nBrotim → Galhim → Cervela → Cervarco. Quatro estágios propostos I Cafifa / II Pipa / III Arraia / IV Pandorga.\n\nArco: sentir correntes, encontrar trilhas, orientar e por fim tecer passagens. A adulta muda a anatomia para cervo-centauro; não é humano montado, nem criatura com duas almas. Quatro pernas sustentam, dois braços manipulam linhas; cabeça continua cervina.\n\n## Identidade\nOrelhas horizontais, cascos fendidos, vinho/ocre/marfim/verde/cobre, membranas rosa nas galhadas e cauda-leque ligada à rabiola. Poucas superfícies amplas de papel, placas legíveis no adulto. Não há obrigação de elemento floresta, tipo mágico, montaria ou habitat definido.\n\n## Pesquisa e limites\nConsultados dois textos do San Diego Zoo sobre renas para galhadas, cascos e grupos. É um membro da família dos cervos; não se afirma que toda característica se aplica a todas as espécies. Função de tecelão é proposta ficcional. Tentativas iniciais de URL de rena e de Centaurmon falharam; não sustentam fatos. Nenhuma imagem externa entrou na geração.\n\n## Produção\nJovem gerado primeiro e inspecionado, adulta criada usando apenas essa referência própria. Criança e bebê por texto, inspecionados individualmente. Contagem de membros e continuidade revisadas; chart validado estruturalmente. Uma vista não prova funcionamento de mecanismos nem sustenta rig. Nenhuma forma aprovada ainda.\n',encoding='utf-8')
(A/'DECISOES.md').write_text('# Direção proposta\n\nAutor pediu linha de cervo. Apresentadas quatro formas; adulta centauro tecelão como especialidade proposta. Nomes, habitat e mecânicas não decididos. Usar 45/45/10 como equilíbrio de direção, não medição. Sem integração.',encoding='utf-8')
sheet=Image.new('RGB',(1800,1500),'#faf4e9');draw=ImageDraw.Draw(sheet);font=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',28);cards=[]
for i,n in enumerate(nodes):
 x=i%2*900;y=i//2*750
